 delete saved.elaMode;delete saved.energy.scoreField;delete saved.energy.scoreThreshold;await h.restoreSession(saved);assert.equal(h.read('elaMode'),'biomes');assert.equal(h.$('energy-biome-controls').hidden,false);assert.equal(h.$('energy-score-controls').hidden,true);assert.equal(h.$('energy-view').value,'overlay');assert.equal(Number(h.$('energy-opacity').value),70);
