 await h.restoreSession(saved);assert.deepEqual(h.read('({params,resultMeta,elaMode,loaded,hash,revision})'),before);assert.equal(h.exec('source'),source);assert.equal(h.exec('fileInput'),file);assert.equal(worker.terminated,undefined);assert.match(h.$('status').textContent,/Erreur/);
