test('draft score previews keep native framing and honest committed metadata; release restores an exportable exact view without rerunning',async()=>{
 const {h,worker}=await calculatedEnergy([640,480]),before=h.read('resultMeta.ui.presentation'),zoom=h.read('zoom'),runCount=worker.calls.filter(call=>call.action==='run').length;
 h.$('energy-score-threshold').emit('pointerdown',{button:0,isPrimary:true});h.$('energy-score-threshold').value='.3';h.$('energy-score-threshold').oninput();const draft=worker.calls.at(-1);
 assert.deepEqual(draft.payload.preview,{maxWidth:320,maxHeight:320});assert.equal(h.$('layer').value,'result');assert.notEqual(h.read('previousPresentation'),null);
 worker.reply(draft,{display:{width:640,height:480,revision:2,preview:true},presentation:{view:'scores',field:'high',threshold:.3,preview:true}});await tick();
 assert.equal(h.read('energyPreviewed'),true);assert.equal(h.read('zoom'),zoom);assert.deepEqual(h.read('resultMeta.ui.presentation'),before);assert.equal(h.$('export-png').disabled,true);assert.equal(h.$('export-report').disabled,true);assert.equal(h.$('energy-npz').disabled,true);
 h.$('energy-score-threshold').emit('pointerup');const exact=worker.calls.at(-1);assert.equal(exact.action,'view-energy');assert.equal(exact.payload.preview,undefined);assert.equal(exact.payload.presentation.threshold,.3);
 worker.reply(exact,{display:{width:640,height:480,revision:3,preview:false},presentation:{view:'scores',field:'high',threshold:.3,scoreView:'map',nativeResolution:true,observedMaximum:2.11}});await tick();
 assert.equal(h.read('energyPreviewed'),false);assert.equal(h.read('zoom'),zoom);assert.equal(h.read('resultMeta.ui.presentation.threshold'),.3);assert.equal(h.$('export-png').disabled,false);assert.equal(h.$('export-report').disabled,false);assert.equal(h.$('energy-npz').disabled,false);assert.equal(worker.calls.filter(call=>call.action==='run').length,runCount);
});
