async function calculatedClassic(dimensions=[640,480]){
 const h=harness(false,{dimensions}),worker=await h.open(),done=h.$('run').onclick(),call=worker.calls.at(-1);
 worker.reply(call,{id:'classic-fixture',operation:'ela.classic',status:'ok',provenance:{operation:'ela.classic',params:call.payload.params},display:{width:dimensions[0],height:dimensions[1],revision:1}});await tick();worker.reply(worker.calls.at(-1),{});await done;
 return{h,worker};
}
async function acceptNative(worker,call,dimensions=[640,480]){
 const energy=call.payload.operation==='ela.energy';worker.reply(call,{id:'final-fixture',operation:call.payload.operation,status:'ok',provenance:{operation:call.payload.operation,params:call.payload.params},...(energy?{data:{metadata:{quality:call.payload.params.quality||75,energy:{quantiles:[.01,.99],thresholds:[5,5]}}},presentation:call.payload.presentation}:{}),display:{width:dimensions[0],height:dimensions[1],revision:90}});await tick();worker.reply(worker.calls.at(-1),{});await tick();
}
test('held Classic spinners coalesce to one latest draft, retain scientific metadata and commit one native result on the same worker',async()=>{
 const {h,worker}=await calculatedClassic(),before=h.read('resultMeta'),zoom=h.read('zoom'),initialRuns=worker.calls.filter(call=>call.action==='run').length;
 h.$('quality').emit('pointerdown',{button:0,isPrimary:true});h.$('quality').value='84';h.$('quality').oninput();const first=worker.calls.at(-1);
 assert.equal(first.action,'preview-classic');assert.equal(first.payload.resultId,'classic-fixture');assert.deepEqual(first.payload.preview,{maxWidth:320,maxHeight:320});assert.equal(h.$('layer').value,'result');assert.notEqual(h.read('previousPresentation'),null);assert.deepEqual(h.read('resultMeta'),before);assert.equal(worker.terminated,undefined);
 for(const value of ['82','80','79']){h.$('quality').value=value;h.$('quality').oninput();}
 assert.equal(worker.calls.filter(call=>call.action==='preview-classic').length,1);assert.equal(worker.calls.filter(call=>call.action==='run').length,initialRuns);assert.equal(h.$('export-png').disabled,true);assert.equal(h.$('export-report').disabled,true);
 worker.reply(first,{display:{width:640,height:480,revision:2,preview:true}});await tick();const last=worker.calls.at(-1);assert.equal(last.action,'preview-classic');assert.equal(last.payload.params.quality,79);assert.equal(h.read('result.previewOnly'),true,'completed drafts publish progressively while only the next input is coalesced');
 worker.reply(last,{display:{width:640,height:480,revision:3,preview:true}});await tick();assert.equal(h.read('elaParameterDraft'),true);assert.equal(h.read('zoom'),zoom);assert.deepEqual(h.read('resultMeta'),before);assert.equal(h.$('quality').disabled,false);
 h.$('quality').emit('pointerup');h.$('quality').emit('blur');h.flush();const exact=worker.calls.at(-1);assert.equal(exact.action,'run');assert.equal(exact.payload.operation,'ela.classic');assert.equal(exact.payload.params.quality,79);assert.equal(worker.calls.filter(call=>call.action==='run').length,initialRuns+1);assert.equal(h.workers.length,1);assert.equal(worker.terminated,undefined);
 await acceptNative(worker,exact);assert.equal(h.read('resultMeta.parameters.quality'),79);assert.equal(h.read('elaParameterDraft'),false);assert.equal(h.read('zoom'),zoom);assert.equal(h.$('export-png').disabled,false);assert.equal(h.$('export-report').disabled,false);
});
