test('30/60 Hz Biome histogram drags paint multiple completed bounded frames during the gesture and commit the latest native value once',async()=>{
 for(const hz of [30,60])for(const key of ['histogramLow','histogramHigh']){
  const {h,worker}=await calculatedEnergy([1031,1024]);h.$('ela-tab-biomes').onclick();worker.reply(worker.calls.at(-1),{display:{width:1031,height:1024,revision:2}});await tick();const control=h.$('energy-'+key);control.min=key==='histogramHigh'?'500':'0';control.max=key==='histogramHigh'?'1000':'500';let inputs=0,maxOutstanding=0,outstanding=0;const responseTimers=new Set();
  worker.onCall=call=>{if(call.action!=='preview-energy-parameters')return;outstanding++;maxOutstanding=Math.max(maxOutstanding,outstanding);const timer=setTimeout(()=>{responseTimers.delete(timer);outstanding--;worker.reply(call,{display:{width:1031,height:1024,revision:call.id,preview:true}});},87);responseTimers.add(timer);};
  control.emit('pointerdown',{button:0});const input=()=>{inputs++;control.value=String(key==='histogramHigh'?990-inputs:10+inputs);control.oninput();};input();const interval=setInterval(input,1000/hz);
  try{await new Promise(resolve=>setTimeout(resolve,580));}finally{clearInterval(interval);}
  const value=Number(control.value),painted=new Set(h.paintedFrames.filter(Number.isFinite));assert.ok(inputs>=hz*.45);assert.ok(h.previewFrames.length>2,'completed drafts must publish even though every request receives newer inputs');assert.ok(painted.size>2,'the immutable RGB frames actually reach the main canvas during the gesture');assert.equal(maxOutstanding,1);assert.equal(worker.calls.filter(call=>call.action==='run').length,1);assert.equal(worker.calls.filter(call=>call.action==='read-display').length,0,'preview canvases never race worker revision reads');assert.equal(h.read('lastScientificEnergy.id'),'energy-fixture');assert.equal(h.$('energy-npz').disabled,true);
  const published=h.previewFrames.length;control.emit('pointerup');control.emit('blur');await new Promise(resolve=>setTimeout(resolve,110));assert.equal(h.previewFrames.length,published,'a completed snapshot after release is abandoned');h.flush();const exact=worker.calls.at(-1);assert.equal(exact.action,'run');assert.equal(exact.payload.params[key],value);assert.equal(worker.calls.filter(call=>call.action==='run').length,2);assert.equal(h.workers.length,1);await acceptNative(worker,exact,[1031,1024]);worker.onCall=null;for(const timer of responseTimers)clearTimeout(timer);assert.equal(h.$('energy-npz').disabled,false);
 }
});
